INSERT OR REPLACE INTO charts (slug, family, title, subtitle, provenance, updated_at)
VALUES ('intl-market-gini-age', 'intl', 'Market-income Gini by age group, US and OECD peers', 'Gini coefficient of market income by age group, latest available year per country (OECD IDD)', '{"bruenig_post_url": "https://peoplespolicyproject.org/2025/10/31/crunching-the-numbers-on-predistribution/", "bruenig_post_title": "Crunching the Numbers on Predistribution", "source_name": "OECD Income Distribution Database (DF_IDD)", "source_url": "https://sdmx.oecd.org/public/rest/v1/data/OECD.WISE.INE,DSD_WISE_IDD@DF_IDD/.A.INC_MRKT_GINI._Z.0_TO_1.Y18T65+Y_GT65+_T.METH2012.D_CUR._Z", "source_detail": "SDMX CSV, key dims documented in recipe", "recipe_md": "Market-income Gini by age group across OECD countries \u2014 reproduces the\nOECD chart in \"Crunching the Numbers on Predistribution\" (Oct 2025).\n\nSource: OECD IDD (DF_IDD), measure INC_MRKT_GINI, unit 0_TO_1,\nmethodology METH2012 / definition D_CUR, age groups Y18T65\n(working-age 18-65), Y_GT65 (over 65), _T (all). Bruenig''s original used\n2019; ours shows each country''s latest available year.\n\nx values are ''ISO3:YYYY'' (country : latest data year); each country has\nthree series (working-age, 65+, total).\n", "original_charts": [{"title": "Market Income Gini by Age Group, 2019, OECD", "source_url": "https://www.peoplespolicyproject.org/static/uploads/2025/10/Market-Income-Gini-by-Age-Group-2019-OECD.svg", "r2_key": "originals/intl-market-gini-age/Market-Income-Gini-by-Age-Group-2019-OECD.svg"}], "original_window": {"first_x": null, "last_x": null}}', '2026-09-26 18:59:42');

